INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish8', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":14,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Noah spiser et æble i frikvarteret. Bagefter spiller han bold.' Hvad gør Noah, når han har spist?","o":["Han spiller bold","Han læser en bog","Han spiser et æble","Han går hjem"],"a":"Han spiller bold","r":"Ordet 'bagefter' viser, hvad der sker efter æblet. Der står, at han spiller bold."},
{"l":34,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en hvalp?","o":["en ung kat","en ung hund","en lille fugl","en lille fisk"],"a":"en ung hund","r":"En hvalp er en hundeunge. En ung kat hedder en killing."},
{"l":57,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer bedst: 'Jeg børster mine ___ hver aften.'","o":["læber","ører","tænder","øjne"],"a":"tænder","r":"Man børster tænder med en tandbørste, så de holder sig rene og sunde."},
{"l":75,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klasse 3.b laver drager i dag. Malik klipper, og Ida limer.' Hvem limer?","o":["Malik","Læreren","Hele klassen","Ida"],"a":"Ida","r":"Der står 'Ida limer'. Malik klipper, så det er ham, der bruger saksen."},
{"l":97,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find tillægsordet: 'Emil har en stor taske.'","o":["stor","Emil","har","taske"],"a":"stor","r":"Et tillægsord fortæller, hvordan noget er. Ordet 'stor' fortæller, hvordan tasken er."},
{"l":114,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En cykel har to af dem, og de er runde. Vælg den rigtige stavemåde.","o":["hjull","hjul","hjuul","jull"],"a":"hjul","r":"Ordet skrives med stumt h foran j. Uden h'et ville det ligne ordet for højtiden i december."},
{"l":135,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Clara ser en lille fugl på jorden. Den kan ikke flyve. Hun ringer efter sin far.' Hvad ser Clara?","o":["En lille mus","Et lille egern","En lille fugl","En stor sommerfugl"],"a":"En lille fugl","r":"Den første sætning fortæller, at Clara ser en lille fugl på jorden."},
{"l":156,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et gult og meget dyrt metal, som man laver ringe af. Vælg den rigtige stavemåde.","o":["gull","guldt","gulld","guld"],"a":"guld","r":"Metallet staves med stumt d til sidst. Uden d er det farven 'gul'."},
{"l":175,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer, når der er fem: 'Jeg købte fem ___.'","o":["æbler","æble","æblet","æblerne"],"a":"æbler","r":"Efter 'fem' skal ordet stå i flertal: et æble, fem æbler."},
{"l":196,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Victor har vundet løbet. Han løfter armene og smiler stort. Hans mor klapper.' Hvordan har Victor det?","o":["Han er ked af det","Han er glad og stolt","Han er træt og sulten","Han er sur og skuffet"],"a":"Han er glad og stolt","r":"Han har vundet, og han løfter armene og smiler. Det gør man, når man er glad og stolt."},
{"l":214,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ting kan stå efter 'et': 'Der står et ___ i køkkenet.'","o":["stol","lampe","bord","gryde"],"a":"bord","r":"Det hedder et bord. De andre hedder en: en stol, en lampe, en gryde."},
{"l":237,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad bruger man en nøgle til?","o":["at ringe på en dør","at tænde for lyset","at åbne en flaske","at låse en dør op"],"a":"at låse en dør op","r":"Med en nøgle kan man låse både op og i. Uden den kan man ikke komme ind ad en låst dør."},
{"l":253,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'De to ___ leger i sandkassen.'","o":["piger","pige","pigen","pigerne"],"a":"piger","r":"Efter 'de to' står navneordet i flertal uden -ne: de to piger."},
{"l":274,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'William har mistet en tand. Den lå i hans madpakke. Han lægger den i en lille æske.' Hvor fandt William tanden?","o":["I sengen","I madpakken","I en lille æske","I skoen"],"a":"I madpakken","r":"Der står, at tanden lå i madpakken. Æsken er det sted, han lægger den bagefter."},
{"l":297,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Kæledyret spinder, når du klør det bag øret. Hvordan staves det?","o":["katt","kaat","kat","kad"],"a":"kat","r":"Danske ord ender sjældent på dobbeltkonsonant, så der står kun ét t. Først i 'katte' kommer der to."},
{"l":317,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Asta kigger ud ad vinduet og sukker. Det regner, og fodboldkampen er aflyst.' Hvorfor sukker Asta?","o":["Fordi hun har glemt sine støvler","Fordi hun har tabt kampen","Fordi vinduet står åbent","Fordi kampen er aflyst"],"a":"Fordi kampen er aflyst","r":"Der står, at kampen er aflyst. Den bliver slet ikke spillet, så hun kan heller ikke have tabt den."},
{"l":334,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Fuglen bygger en ___ i træet.'","o":["rede","stald","hule","hytte"],"a":"rede","r":"En rede er fuglens hjem, hvor den lægger sine æg. Den bygges tit af kviste og græs."},
{"l":356,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vand, der falder ned fra skyerne. Hvordan staves det?","o":["rejn","regn","regen","rein"],"a":"regn","r":"Her skrives g, selvom det lyder som j. Bogstaverne g og n står lige efter hinanden."},
{"l":372,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vejen er bred. Hvad er det modsatte af 'bred'?","o":["lav","tung","smal","blød"],"a":"smal","r":"En bred vej har god plads til siderne. På en smal vej er der kun lidt plads."},
{"l":395,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Josefine ser sin bedste ven på perronen. Hun løber hen og giver ham et stort kram. De har ikke set hinanden hele sommeren.' Hvorfor krammer Josefine sin ven?","o":["Hun fryser på perronen","Hun skal sige farvel til ham","Hun vil trøste ham","Hun er glad for at se ham igen"],"a":"Hun er glad for at se ham igen","r":"De har ikke set hinanden hele sommeren. Derfor er hun glad for at møde ham igen."},
{"l":414,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Klokken er ___ fem.'","o":["halv","hall","half","hallv"],"a":"halv","r":"Ordet ender på lv med stumt v. Der er kun ét l."},
{"l":435,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer: 'Der ligger tre ___ på bordet.'","o":["bog","bøger","bogen","bøgerne"],"a":"bøger","r":"Ordet ændrer sig i flertal: en bog, tre bøger. Her bliver o til ø."},
{"l":456,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alberte får en ny cykel, som er alt for høj. Hendes fødder kan ikke nå jorden. Far siger, at de må skrue sadlen ned.' Hvad er problemet med cyklen?","o":["Den har ingen sadel","Den har den forkerte farve","Den er for høj til Alberte","Den er gået i stykker"],"a":"Den er for høj til Alberte","r":"Der står, at cyklen er alt for høj, og at hendes fødder ikke kan nå jorden."},
{"l":473,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nadia så en mus i kælderen. Hun sagde det til sin far. Han satte en fælde med ost, men musen var for klog og gik udenom.' Hvad gjorde musen ved fælden?","o":["Den spiste osten","Den blev fanget","Den flyttede den","Den gik udenom"],"a":"Den gik udenom","r":"Der står, at musen var for klog og gik udenom fælden."},
{"l":492,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord hører til samme ordfamilie som 'bage'?","o":["bageri","bagage","bakke","bagved"],"a":"bageri","r":"Et bageri er et sted, hvor man bager. Bagage er de tasker, man rejser med, så det ord hører ikke til familien."},
{"l":514,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord hører til samme ordfamilie som 'flyve'?","o":["flise","fly","flod","flaske"],"a":"fly","r":"Et fly er noget, der flyver. De andre ord begynder ens, men har ikke noget med at flyve at gøre."},
{"l":534,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tariq vågner og hører ingen lyde. Han kigger ud og ser, at alt er dækket af sne. Skolen er lukket i dag.' Hvad gør det hele så stille?","o":["Solen","Vinden","Sneen","Skolen"],"a":"Sneen","r":"Det nævnes lige efter, at der ingen lyde er, at alt er dækket af sne. Sne dæmper lyde, og ingen kører i det."},
{"l":552,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer: 'I går ___ vi en film.'","o":["ser","se","set","så"],"a":"så","r":"'I går' viser, at det skal stå i datid. Datid af 'at se' er 'så'."},
{"l":574,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer på en, der altid vil vide mere?","o":["nysgerrig","træt","genert","sur"],"a":"nysgerrig","r":"En nysgerrig person stiller mange spørgsmål og vil gerne finde ud af nye ting."},
{"l":595,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Egernet samler nødder om efteråret. Det gemmer dem mange steder i skoven. Om vinteren finder det nogle af dem igen.' Hvorfor gemmer egernet nødder?","o":["For at give dem til fuglene","For at have mad om vinteren","For at få nye træer i skoven","For at lege med dem om foråret"],"a":"For at have mad om vinteren","r":"Egernet finder nødderne igen om vinteren. Det er det forråd, det skal leve af, når der er lidt mad."},
{"l":612,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Noah tør næsten ikke sige noget, når han møder nye mennesker. Hvordan er han?","o":["vred","stolt","genert","nysgerrig"],"a":"genert","r":"Den, der er genert, bliver let stille og usikker over for mennesker, man ikke kender."},
{"l":634,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'opdage' noget?","o":["at gemme det","at lede efter det","at glemme det","at finde ud af det"],"a":"at finde ud af det","r":"Når man opdager noget, lægger man mærke til det eller finder det for første gang."},
{"l":656,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det er lavet af glas, og du kan kigge ud gennem det. Vælg den rigtige stavemåde.","o":["vindue","vinnue","vindu","vinndue"],"a":"vindue","r":"Ordet skrives med nd, og d'et kan høres. Ordet slutter på -ue."},
{"l":672,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Rummet under huset, hvor der tit står cykler og gammelt legetøj. Hvordan staves det?","o":["kæller","kælder","kælær","kjælder"],"a":"kælder","r":"D'et er stumt, men det skal skrives. Ordet slutter på -er."},
{"l":694,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mener du, hvis du siger, at du er 'sulten som en ulv'?","o":["at du er farlig og vild","at du har meget hår","at du trænger meget til mad","at du hyler om natten"],"a":"at du trænger meget til mad","r":"Det er et billede på, at man er meget sulten. Man bliver ikke til en ulv af det."},
{"l":714,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du skriver med den, og skriften kan viskes ud. Hvilket ord er stavet rigtigt?","o":["blyent","bliant","blyantt","blyant"],"a":"blyant","r":"Ordet skrives med y og slutter på ant."},
{"l":733,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Aske havde lagt sine klodser i en lang række. Hans lillesøster kom kravlende og væltede det hele. Aske kiggede på hende og sagde ingenting, men han rejste sig og gik.' Hvordan havde Aske det?","o":["Han var irriteret","Han var bange","Han var stolt","Han var nysgerrig"],"a":"Han var irriteret","r":"Hans lillesøster ødelægger det, han har bygget, og han går væk uden et ord. Det viser, at han er irriteret."},
{"l":754,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man den, der står foran et orkester og leder musikken?","o":["en trommeslager","en dirigent","en tilskuer","en sanger"],"a":"en dirigent","r":"En dirigent viser med hænderne eller en lille pind, hvordan musikerne skal spille."},
{"l":773,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Mine ___ er våde efter turen.'","o":["fod","foden","fødder","fødderne"],"a":"fødder","r":"En fod bliver til to fødder med ø og dobbelt d. Efter 'mine' bruger man ikke den bestemte form 'fødderne'."},
{"l":794,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mariehønen ser sød ud, men den er en god jæger. Den spiser mange bladlus. Derfor bliver gartnere glade, når de ser den på deres roser.' Hvorfor er gartnere glade for mariehøns?","o":["De ser søde ud i bedet","De lægger æg på roserne","De spiser alt ukrudtet","De spiser bladlusene"],"a":"De spiser bladlusene","r":"Teksten siger, at mariehønen spiser mange bladlus. Bladlus skader roserne, så gartneren får hjælp."},
{"l":812,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form har navneordet 'husene'?","o":["bestemt flertal","bestemt ental","ubestemt flertal","ubestemt ental"],"a":"bestemt flertal","r":"Der er flere huse, og endelsen -ne viser, at det er nogle bestemte huse."},
{"l":831,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Hunden ___ i sin kurv lige nu.'","o":["sove","sover","sovver","såver"],"a":"sover","r":"Nutid har -r til sidst. Ordet skrives med o, selvom det kan lyde som å."},
{"l":852,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvordan er en person, der altid siger sandheden?","o":["stædig","doven","ærlig","modig"],"a":"ærlig","r":"En ærlig person lyver ikke, heller ikke når det er svært at sige sandheden."},
{"l":874,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Nadia har tabt sin nøgle, men nu finder hun den igen. Hvordan har hun det?","o":["misundelig","flov","skuffet","lettet"],"a":"lettet","r":"Man er lettet, når en bekymring forsvinder. Det føles, som om noget tungt bliver taget af en."},
{"l":890,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tvillingerne er søde. Hvilket ord passer: 'Vi leger tit med ___.'","o":["dem","de","deres","vi"],"a":"dem","r":"Efter 'med' skal der stå 'dem'. 'De' bruger man, når tvillingerne selv gør noget."},
{"l":914,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Hun ___ bogen på bordet i går.'","o":["lae","lagde","laide","laggede"],"a":"lagde","r":"Ordet skrives med stumt g og d. Det er datid af 'lægge', ligesom 'sagde' er datid af 'sige'."},
{"l":933,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Trækfugle flyver mod syd om efteråret, fordi der bliver for lidt mad her. Om foråret vender de tilbage for at bygge rede.' Hvorfor flyver trækfuglene mod syd?","o":["Fordi de skal bygge rede dér","Fordi deres unger bor dér","Fordi de skal finde mad","Fordi de elsker at flyve langt"],"a":"Fordi de skal finde mad","r":"Teksten siger, at der bliver for lidt mad her om efteråret. Derfor flyver de til steder med mere."},
{"l":950,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Først vågnede Ida. Så spiste hun morgenmad. Til sidst gik hun i skole.' Hvad sker der i midten af teksten?","o":["Ida vågner om morgenen","Ida går i skole","Ida går i seng","Ida spiser morgenmad"],"a":"Ida spiser morgenmad","r":"Ordet 'først' viser begyndelsen, og 'til sidst' viser slutningen. Det, der sker imellem, er midten."},
{"l":972,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Far sagde: »vi skal hjem nu.«'?","o":["vi","sagde","skal","hjem"],"a":"vi","r":"Det, far siger, er en hel sætning for sig selv. Derfor begynder den direkte tale med stort bogstav."},
{"l":994,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Engelsk, tysk og fransk hører sammen. Hvad er de alle sammen?","o":["lande","sprog","byer","øer"],"a":"sprog","r":"Det er navne på sprog, man taler. Landene hedder for eksempel England og Tyskland."},
{"l":1014,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Vi havde en ___ dag på stranden.'","o":["dejli","dajlig","dejlig","deilig"],"a":"dejlig","r":"Ordet ender på -lig, selvom g'et er stumt. Der står j efter e."},
{"l":1032,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mener man, når man siger, at en pige har 'ben i næsen'?","o":["at hun har brækket næsen","at hun sover meget længe","at hun løber meget hurtigt","at hun tør sige sin mening"],"a":"at hun tør sige sin mening","r":"Den, der har ben i næsen, kan klare sig selv og tør stå fast."},
{"l":1054,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'købe katten i sækken'?","o":["at købe noget, der viser sig at være dårligt","at købe noget, der er meget billigt","at købe et kæledyr i en dyrehandel","at købe en gave til en god ven"],"a":"at købe noget, der viser sig at være dårligt","r":"Køber man noget uden at se det ordentligt, kan man blive snydt, som hvis sækken gemte en kat i stedet for det, man troede."},
{"l":1072,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tre af linjerne om regnvejr er sætninger. Hvilken er ikke en sætning?","o":["Det regner i dag.","En våd dag i april.","Vi bliver våde.","Paraplyen er rød."],"a":"En våd dag i april.","r":"Her er der ikke noget udsagnsord. De andre har både grundled og udsagnsled."},
{"l":1092,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler der komma: 'Mor far og jeg tog til stranden.'?","o":["far","og","Mor","jeg"],"a":"Mor","r":"Sætningen opremser tre personer. Komma står mellem 'Mor' og 'far', og foran 'og' skal der ikke komma."},
{"l":1114,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et spil på en stor græsbane med elleve spillere på hvert hold. Hvilket ord er stavet rigtigt?","o":["fodbol","foldbold","fod bold","fodbold"],"a":"fodbold","r":"Ordet består af 'fod' og 'bold' og skrives i ét ord. Begge dele beholder deres d."},
{"l":1132,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der var kun én bog om dinosaurer tilbage på biblioteket. Muhammed og Ea greb efter den på samme tid. De lo og satte sig til at læse den sammen. Fra den dag sad de altid ved siden af hinanden.' Hvad blev starten på deres venskab?","o":["At de ville have den samme bog","At de gik i samme klasse","At de lavede en opgave sammen","At de kom på biblioteket hver dag"],"a":"At de ville have den samme bog","r":"De greb efter den samme bog, og så læste de den sammen. Der står ikke noget om klasse eller opgave."},
{"l":1152,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Ida kan næsten ikke vente med at komme i gang. Hun er meget ___.'","o":["doven","ivrig","ligeglad","søvnig"],"a":"ivrig","r":"Den, der er ivrig, har stor lyst til at gå i gang med noget med det samme."},
{"l":1172,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Pladsen uden for skolen, hvor eleverne leger. Vælg den rigtige stavemåde.","o":["skolegår","skolegord","skolegård","skole gård"],"a":"skolegård","r":"Ordet består af 'skole' og 'gård' og skrives i ét ord. Husk det stumme d."},
{"l":1189,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er datid af 'at skrive'?","o":["skriver","skrevet","skrive","skrev"],"a":"skrev","r":"'Skriver' er nutid, og 'skrevet' bruges efter 'har'. Datid er 'skrev'."},
{"l":1212,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om sneen har kommaet det rigtige sted?","o":["Vi bygger en snemand, en hule og en bakke.","Vi bygger, en snemand en hule og en bakke.","Vi bygger en snemand en hule, og en bakke.","Vi bygger en snemand en hule og, en bakke."],"a":"Vi bygger en snemand, en hule og en bakke.","r":"Der står komma mellem de ting, man opremser. Foran 'og' skal der ikke komma."},
{"l":1234,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'beslutte'?","o":["forklare","bestemme","opdage","gætte"],"a":"bestemme","r":"Når man beslutter noget, bestemmer man sig for, hvad der skal ske."},
{"l":1253,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Søstjernen har ikke noget hoved. Hvis den mister en af sine arme, kan der vokse en ny ud. Det tager dog lang tid.' Hvad er særligt ved søstjernen?","o":["Den har mange hoveder","Den kan svømme hurtigt","Den kan få en ny arm","Den lever på land"],"a":"Den kan få en ny arm","r":"Teksten fortæller, at der kan vokse en ny arm ud, hvis søstjernen mister en."},
{"l":1272,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Mange bække små gør en stor å'?","o":["at man ikke må lege i nærheden af vand","at det altid er bedst at bo tæt på en å","at store ting altid er bedre end små ting","at mange små ting kan blive til noget stort"],"a":"at mange små ting kan blive til noget stort","r":"Små vandløb løber sammen til en stor å. På samme måde kan små beløb på sparegrisen blive til mange penge."},
{"l":1293,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Mine ___ støvler er slidte.'","o":["gamle","gammel","gammelt","ældst"],"a":"gamle","r":"Støvlerne er flere, og tillægsordet får -e. Læg mærke til, at det ene m og e'et falder væk: gamle."},
{"l":1314,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Du er min ___ ven.'","o":["beste","bedste","bæste","bedsde"],"a":"bedste","r":"Ordet er højeste grad af 'god'. Det har et stumt d foran s."},
{"l":1332,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Ingen roser uden torne'?","o":["at man altid skal bruge handsker i haven","at roser er de flotteste af alle blomster","at det gode tit også har en dårlig side","at man aldrig må plukke blomster i parken"],"a":"at det gode tit også har en dårlig side","r":"Roser er smukke, men de har torne, som stikker. Sådan følger der tit noget svært med det gode."},
{"l":1354,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'lægge hovedet i blød'?","o":["at vaske sit hår i varmt vand","at sove på en meget blød pude","at bade længe i et stort badekar","at tænke grundigt over noget"],"a":"at tænke grundigt over noget","r":"Vask, der ligger i blød, får god tid. Sådan giver man også hovedet god tid til at finde en løsning."},
{"l":1372,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Hun fik ___ plads i løbet.'","o":["første","føste","førsde","førrste"],"a":"første","r":"Der står et r før s, selvom man næsten ikke kan høre det."},
{"l":1392,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rami og Sif lagde et brev under Stines dør. I brevet stod der, at de var kede af skænderiet. Lidt efter gik døren op, og Stine smilede forsigtigt til dem.' Hvad kan man slutte?","o":["At Stine stadig er rasende","At Stine vil være venner igen","At Stine aldrig fik brevet","At Rami og Sif vil skændes mere"],"a":"At Stine vil være venner igen","r":"Stine åbner døren og smiler efter brevet. Det viser, at hun har læst undskyldningen og tager imod den."},
{"l":1410,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord fortæller, hvordan suppen er: 'Suppen i gryden er varm.'","o":["Suppen","gryden","varm","er"],"a":"varm","r":"Tillægsordet 'varm' behøver ikke stå lige foran navneordet. Det fortæller stadig, hvordan suppen er."},
{"l":1431,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hanne har fundet en bog på loftet. Den er fra dengang, hendes mormor gik i skole. Inde i bogen ligger der en tørret blomst og et lille brev.' Hvor gammel er bogen nok?","o":["Et par år gammel","Over tusind år gammel","Få dage gammel","Mange år gammel"],"a":"Mange år gammel","r":"Bogen er fra mormors skoletid. Det må være mange år siden."},
{"l":1452,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Mina bærer altid de andres tasker. Hun er en ___ pige.'","o":["hjælpsom","jælpsom","hjælbsom","hjælpsomm"],"a":"hjælpsom","r":"Ordet begynder med stumt h. Endelsen -som skrives med ét m."},
{"l":1471,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et stort skovdyr med gevir. Hvilken stavemåde er rigtig?","o":["jort","hjort","hjordt","hjårt"],"a":"hjort","r":"Dyret begynder med stumt h og slutter på rt. Det skrives med o."},
{"l":1491,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man de dele af et træ, der sidder nede i jorden?","o":["grenene","kronen","rødderne","stammen"],"a":"rødderne","r":"Rødderne holder træet fast og suger vand op fra jorden. Stammen står over jorden."},
{"l":1512,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vikingerne sejlede i langskibe. Skibene var lette og kunne sejle på meget lavt vand. Derfor kunne vikingerne komme langt op ad floder.' Hvorfor kunne vikingerne sejle op ad floder?","o":["Fordi skibene havde mange sejl","Fordi floderne var meget dybe","Fordi vikingerne var stærke roere","Fordi skibene kunne sejle på lavt vand"],"a":"Fordi skibene kunne sejle på lavt vand","r":"Ordet 'derfor' knytter det sammen: Skibene kunne sejle på lavt vand, og så kunne de komme op ad floder."},
{"l":1530,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores klasse har fået to nye høns. Mandag er det Lucas, der fodrer dem, og tirsdag er det Mira. Onsdag har Mira fri, så Omar tager hendes tur, selvom han fodrede dem i sidste uge.' Hvem fodrer hønsene onsdag?","o":["Omar","Lucas","Mira","Læreren"],"a":"Omar","r":"Der står, at Omar tager turen om onsdagen. Mira har fri den dag."},
{"l":1550,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes den person i en historie, der kæmper imod hovedpersonen?","o":["en hjælper","en modstander","en fortæller","en forfatter"],"a":"en modstander","r":"Modstanderen står i vejen for det, hovedpersonen vil. Det skaber spænding i historien."},
{"l":1573,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er ubestemt ental af 'gulerødderne'?","o":["gulerødder","guleroden","gulerod","gulerodens"],"a":"gulerod","r":"Ubestemt ental er den form, der står efter 'en': en gulerod. 'Guleroden' er bestemt form."},
{"l":1593,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Grønland er verdens største ø. Det meste af øen er dækket af is. Derfor bor næsten alle mennesker langs kysten, hvor der ikke er is.' Hvorfor bor næsten alle grønlændere ved kysten ifølge teksten?","o":["Fordi fiskene kan fanges dér","Fordi der er varmest i byerne","Fordi alle grønlændere har en båd","Fordi det meste af landet er is"],"a":"Fordi det meste af landet er is","r":"Teksten forklarer med 'derfor', at folk bor ved kysten, fordi øens indre er dækket af is."},
{"l":1611,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Agnes sad helt stille på første række og holdt sin fars hånd så hårdt, at knoerne blev hvide. På lærredet nærmede dragen sig langsomt den lille landsby.' Hvor er Agnes?","o":["I biografen","I teatret","På et museum","Hjemme i stuen"],"a":"I biografen","r":"Et lærred og en historie med en drage passer med en film. Hun sidder på en række i biografen."},
{"l":1632,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet ved havet, hvor du kan bade og bygge sandslotte. Hvordan staves det?","o":["strandt","strand","strann","strannd"],"a":"strand","r":"Ordet ender på nd med stumt d, og der er ét n."},
{"l":1651,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Katten er tam, men tigeren er ___.'","o":["vill","villd","vild","vildd"],"a":"vild","r":"Ordet ender på stumt d. Uden d er det 'vil' af 'at ville'."},
{"l":1670,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken figur bor i Villa Villekulla sammen med en abe og en hest?","o":["Ronja Røverdatter","Alice i Eventyrland","Matilda","Pippi Langstrømpe"],"a":"Pippi Langstrømpe","r":"Pippi Langstrømpe er verdens stærkeste pige. Hun bor alene i Villa Villekulla med aben Hr. Nilsson og sin hest."},
{"l":1692,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores dyrlæge Mette har travlt om foråret. Så får mange får lam, og nogle gange skal hun hjælpe. I sidste uge hjalp hun tre lam til verden på én nat.' Hvorfor er der travlt om foråret?","o":["Mange får får lam","Mange får bliver syge","Mange lam skal vaccineres","Mange får løber væk"],"a":"Mange får får lam","r":"Teksten siger, at mange får får lam om foråret, og at dyrlægen nogle gange skal hjælpe."},
{"l":1711,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'hidsig'?","o":["stærk","rolig","klog","trist"],"a":"rolig","r":"En hidsig person bliver hurtigt vred, mens en rolig person bevarer freden, også når noget går galt."},
{"l":1730,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er typisk for et eventyr?","o":["Det fortæller om noget, der virkelig er sket for længe siden","Det handler altid om dyr, der vil lære os noget","Der sker ting, som ikke kan ske i virkeligheden","Det er altid skrevet på rim"],"a":"Der sker ting, som ikke kan ske i virkeligheden","r":"I et eventyr kan dyr tale, og der kan ske trylleri. Det er opdigtet, også selvom det foregår for længe siden."},
{"l":1753,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige ord: 'Jeg ___ bogen på bordet for lidt siden.'","o":["lå","ligger","lægge","lagde"],"a":"lagde","r":"Her flytter jeg selv bogen, så det er 'at lægge', og i datid hedder det 'lagde'. 'Lå' er datid af 'at ligge'."},
{"l":1773,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi har to sæt tænder i løbet af livet. Først kommer mælketænderne, som falder ud, når vi er børn. De bliver afløst af de blivende tænder, som skal holde resten af livet.' Hvad betyder 'afløst' her?","o":["Skiftet ud","Gjort rene","Trukket ud","Gjort større"],"a":"Skiftet ud","r":"De blivende tænder kommer i stedet for mælketænderne. De bliver altså skiftet ud."},
{"l":1791,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør 'lungerne' i kroppen?","o":["De pumper blodet rundt i kroppen.","De tager ilt ind fra luften.","De fordøjer al den mad, du spiser.","De styrer alle dine tanker."],"a":"De tager ilt ind fra luften.","r":"Når du trækker vejret, fyldes lungerne med luft, og ilten går videre ud i blodet. Det er hjertet, der pumper blodet rundt."},
{"l":1813,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Dommeren blæser i sin ___, når kampen er slut.'","o":["fløite","fløjde","fløjte","fløgte"],"a":"fløjte","r":"Ordet skrives med øj og slutter på -te."},
{"l":1832,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det måltid, du spiser midt på dagen. Hvordan staves det?","o":["frokåst","frukost","frookost","frokost"],"a":"frokost","r":"Ordet skrives med o begge steder og slutter på -st."},
{"l":1851,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et meget højt sted i landskabet med sne på toppen. Find den rigtige stavemåde.","o":["bjerg","bjærg","bjerk","bjerrg"],"a":"bjerg","r":"Ordet skrives med e, selvom det lyder som æ, og det slutter på g."},
{"l":1872,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Om vinteren har mange træer hverken blade eller frugter. Fuglene kan derfor have svært ved at finde mad. Derfor hænger mange mennesker fuglefoder op i haven.' Hvorfor hænger mange fuglefoder op?","o":["For at pynte i haven","For at hjælpe fuglene gennem vinteren","For at holde fuglene væk fra huset","For at træerne skal gro bedre"],"a":"For at hjælpe fuglene gennem vinteren","r":"Det er svært for fuglene at finde mad om vinteren. Foderet hjælper dem."},
{"l":1890,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der er to slags cykelhjelme i butikken. Den ene er dyr og flot, men sidder løst. Den anden er billig, og den sidder godt fast på hovedet. Far valgte den billige.' Hvorfor valgte far nok den billige hjelm?","o":["Fordi den billige hjelm var flottest","Fordi den dyre hjelm sad for stramt","Fordi hjelmen skal sidde godt fast","Fordi den flotte hjelm var for lille"],"a":"Fordi hjelmen skal sidde godt fast","r":"Det vigtigste ved en hjelm er, at den sidder fast, så den beskytter. Det gjorde den billige."},
{"l":1910,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken slags tekst i en avis fortæller om noget, der lige er sket?","o":["en vejrudsigt","en annonce","en tegneserie","en nyhedsartikel"],"a":"en nyhedsartikel","r":"En nyhedsartikel handler om noget virkeligt, der lige er sket. En vejrudsigt handler om det, der kommer, og en annonce vil sælge noget."},
{"l":1932,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det blæste så meget, at Ahmed måtte træde hårdt i pedalerne for at komme fremad. Da han vendte om og kørte hjem igen, kunne han næsten holde fødderne stille.' Hvorfor gik det så let på vej hjem?","o":["Fordi vinden kom bagfra","Fordi vinden var løjet af","Fordi cyklen var blevet lettere","Fordi vejen hjem var kortere"],"a":"Fordi vinden kom bagfra","r":"Ud ad vejen havde han modvind. Når han vender om, kommer vinden i stedet bagfra og skubber ham."},
{"l":1950,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mohamed jonglerede med fem bolde i et helt minut. Da den sidste bold landede i hans hånd, blev der helt stille i klassen. Så begyndte først én at klappe, og lidt efter klappede alle.' Hvad viser klappene?","o":["At de andre ville have ham til at holde op","At de andre syntes, det var flot","At de andre grinede ad ham","At de andre var utålmodige"],"a":"At de andre syntes, det var flot","r":"Alle klapper, efter at han har vist noget svært. Det gør man, når man synes, det var flot."},
{"l":1970,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken sætning viser tydeligt, at historien har en jeg-fortæller?","o":["'Jeg kan ikke sove,' sagde Mia.","Mia kunne ikke sove hele natten.","Jeg kunne ikke sove hele natten.","'Sover du?' spurgte hun."],"a":"Jeg kunne ikke sove hele natten.","r":"En jeg-fortæller er selv med i historien og siger 'jeg'. I ''Jeg kan ikke sove,' sagde Mia' er det Mia, der taler, og ikke den, der fortæller."},
{"l":1993,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den lange, grønne grøntsag, som tit ligger i salaten. Hvordan staves den?","o":["agurg","aggurk","akurk","agurk"],"a":"agurk","r":"Ordet skrives med ét g i midten og slutter på k."},
{"l":2012,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den vokser i haven og dufter godt. Vælg den rigtige stavemåde.","o":["blomst","blomsd","blommst","blonst"],"a":"blomst","r":"Ordet slutter på -mst med ét m."},
{"l":2031,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det søde, du kommer på brødet, og som er kogt af bær. Hvilket ord er stavet rigtigt?","o":["sylttøj","syltetøj","syltetøi","sylte tøj"],"a":"syltetøj","r":"Ordet består af 'sylte' og 'tøj' og skrives i ét ord. Det slutter på øj."},
{"l":2050,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Jeg vil gerne ___ at svømme.'","o":["lærer","lærre","lære","lærær"],"a":"lære","r":"Efter 'vil' skal udsagnsordet stå i navneform uden -r."},
{"l":2070,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en 'stædig' person?","o":["siger ja til alt, andre foreslår","giver hurtigt op og går hjem","hjælper gerne alle andre","holder fast i sin mening"],"a":"holder fast i sin mening","r":"En stædig person vil ikke give sig, heller ikke når andre prøver at få ham eller hende til at skifte mening."},
{"l":2089,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket stedord passer: 'I ___ klasse går der 22 elever.'","o":["vores","vi","os","mig"],"a":"vores","r":"Ordet viser, hvem klassen hører til. 'Vores' viser det, mens 'vi' og 'os' ikke kan stå foran 'klasse'."},
{"l":2112,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Miriam åbnede pakken og blev helt stille. Det var en bog, hun allerede havde. Så kiggede hun op på sin bedstefar, som sad og smilede forventningsfuldt, og sagde: Tusind tak, den har jeg lige ønsket mig.' Hvorfor sagde Miriam det?","o":["Hun havde glemt, at hun ejede bogen","Hun ville ikke skuffe sin bedstefar","Hun ville gerne have to af den","Hun troede, at det var en anden bog"],"a":"Hun ville ikke skuffe sin bedstefar","r":"Hun ved godt, at hun har bogen, men bedstefar smiler spændt. Hun siger det for at glæde ham."},
{"l":2130,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"I en tegneserie står teksten i en sky, der er forbundet med personen af små cirkler. Hvad betyder det?","o":["Personen siger det højt","Personen råber det","Personen tænker det","Personen synger det"],"a":"Personen tænker det","r":"Det er en tænkeboble. De små cirkler i stedet for en spids viser, at personen ikke siger det højt."},
{"l":2149,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvor mange stedord er der i sætningen: 'Jeg ringer til dig, når vi er hjemme.'","o":["to","fire","ét","tre"],"a":"tre","r":"Stedordene er 'jeg', 'dig' og 'vi'. De står alle i stedet for personers navne."},
{"l":2173,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'på' i sætningen: 'Bogen ligger på hylden.'","o":["forholdsord","bindeord","stedord","tillægsord"],"a":"forholdsord","r":"'På' viser, hvor bogen er i forhold til hylden. Det gør et forholdsord."},
{"l":2190,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Maja og Ali holdt en ___ for klassen om vulkaner.'","o":["fremtid","fremlæggelse","fremgang","fremmed"],"a":"fremlæggelse","r":"Ved en fremlæggelse fortæller man om et emne for de andre i klassen."},
{"l":2211,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Roald var kendt for at kunne det hele. Da læreren spurgte, om nogen vidste, hvad en kompasnål peger mod, var hans hånd oppe, før hun var færdig med at tale.' Hvad betyder 'var kendt for' her?","o":["At han ikke vidste noget","At han havde et kendt navn","At mange vidste det om ham","At han var berømt i tv"],"a":"At mange vidste det om ham","r":"Det betyder, at folk omkring ham vidste, at han kunne det hele."},
{"l":2231,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken flertalsform er rigtig: 'Vores klasselokale har fire store ___.'","o":["vinduere","vindur","vinnduer","vinduer"],"a":"vinduer","r":"Ordet får flertals-r direkte efter e'et. D'et i midten skal med, og det kan høres."},
{"l":2250,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad har du gjort, hvis du har 'forspist' dig?","o":["Du har spist alt for meget.","Du har spist alt for lidt.","Du har spist alt for sent.","Du har spist alt for tidligt."],"a":"Du har spist alt for meget.","r":"Har du forspist dig, er du så mæt, at det føles ubehageligt. Her betyder for-, at det er for meget."},
{"l":2269,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Harer har to lange ___.'","o":["ørerer","ører","øreer","ørrer"],"a":"ører","r":"Flertal af 'øre' får -r direkte efter e'et."},
{"l":2292,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I skolegården stod en gammel kastanje. Den var ved at gå ud, og kommunen ville fælde den. Eleverne skrev et brev og bad om at få lov til at beholde træet. Kommunen svarede, at de nu ville plante nye kastanjer ved siden af.' Hvad opnåede eleverne?","o":["At kastanjen bliver rask igen","At eleverne selv skal plante træerne","At kommunen vil plante nye kastanjer","At skolen får en ny skolegård"],"a":"At kommunen vil plante nye kastanjer","r":"Kommunen svarede på brevet, at den vil plante nye træer. Der står ikke, at det gamle træ bliver rask."},
{"l":2310,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'modig'?","o":["træt","flink","klog","fej"],"a":"fej","r":"En modig person tør noget svært, mens en fej person ikke tør og løber fra det."},
{"l":2329,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet i spørgsmålet: 'Spiser Malthe med i aften?'","o":["Malthe","Spiser","med","i aften"],"a":"Malthe","r":"Spørg: Hvem spiser med? Det gør Malthe. Udsagnsleddet står først, fordi det er et spørgsmål."},
{"l":2353,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er grundleddet: 'Lea og Hamza bygger en hule i skoven.'","o":["bygger","Lea og Hamza","en hule","i skoven"],"a":"Lea og Hamza","r":"Begge børn bygger, så begge navne hører med til grundleddet."},
{"l":2370,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'ulempe'?","o":["noget, der gør arbejdet lettere","noget, man får lov til i weekenden","den dårlige side ved noget","en stor glæde ved noget nyt"],"a":"den dårlige side ved noget","r":"Mange ting har både fordele og ulemper. Det er dejligt at have en hund, men en ulempe er, at den også skal luftes i regnvejr."},
{"l":2389,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken linje om bussen kan stå alene som en hel sætning?","o":["Fordi bussen kom for sent.","Da bussen kom for sent.","Hvis bussen kom for sent.","Bussen kom for sent."],"a":"Bussen kom for sent.","r":"De tre andre begynder med et ord, der gør, at de mangler en sætning at hænge på."},
{"l":2411,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Faget, hvor du regner med tal og figurer. Hvordan staves det?","o":["matematik","mattematik","matemmatik","matematig"],"a":"matematik","r":"Ordet har kun enkelte konsonanter og slutter på -ik."},
{"l":2430,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'forbillede'?","o":["et billede forrest i en bog om dyr","en, man ser op til og gerne vil ligne","en tegning, man laver før et maleri","en person, der står forrest i køen"],"a":"en, man ser op til og gerne vil ligne","r":"Et forbillede er en person, som man gerne vil være som. Ordet handler om et menneske og ikke om et rigtigt billede."},
{"l":2449,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Jeg kan ___ ikke komme til din fest.'","o":["desvære","desværere","desværre","dessværre"],"a":"desværre","r":"Ordet skrives med ét s og to r'er til sidst."},
{"l":2469,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Danmark har mere end 400 navngivne øer, men kun en del af dem er beboede. Mange øer er så små, at der kun bor fugle. Bornholm ligger langt mod øst, Lolland mod syd og Fyn midt i landet. Sjælland er den største, og flest mennesker bor dér.' Hvilken ø bor der flest mennesker på?","o":["Fyn","Bornholm","Lolland","Sjælland"],"a":"Sjælland","r":"Sidste sætning siger, at der bor flest mennesker på Sjælland. De andre øer nævnes kun for, hvor de ligger."},
{"l":2487,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fra toppen af Rundetårn kan man se langt ud over København. Vejen op er ikke en trappe, men en lang snoet gang. Den blev bygget i 1600-tallet.' Hvad passer ikke med teksten?","o":["At man går op ad en trappe","At vejen op er lang og snoet","At man kan se langt fra toppen","At gangen er fra 1600-tallet"],"a":"At man går op ad en trappe","r":"Teksten siger lige ud, at vejen op ikke er en trappe, men en lang snoet gang. De tre andre svar står alle i teksten."},
{"l":2509,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tre af ordene er udsagnsord i navneform. Hvilket er et navneord?","o":["bygge","bygning","hente","vente"],"a":"bygning","r":"Endelsen -ning viser ofte et navneord: en bygning. De andre kan stå efter 'at'."},
{"l":2532,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Forfatteren begynder sin bog med en stor mørk skov. Træerne står tæt, og ingen fugl synger. Hovedpersonen bliver mere og mere bange for hver side.' Hvorfor fortæller forfatteren om den mørke skov?","o":["For at forklare, hvordan man fælder træer","For at vise, at skoven er et hyggeligt sted","For at gøre historien uhyggelig","For at vise, hvor fuglene holder til"],"a":"For at gøre historien uhyggelig","r":"Mørke, tætte træer og stilhed gør os bange sammen med hovedpersonen. Det gør historien uhyggelig."},
{"l":2550,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket udsagnsord hører til navneordet 'beslutning'?","o":["beskytte","beskrive","besøge","beslutte"],"a":"beslutte","r":"Når man beslutter noget, træffer man en beslutning. Endelsen -ning laver mange navneord af udsagnsord."},
{"l":2569,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad kalder man ordene 'en' og 'et', når de står foran et navneord?","o":["kendeord","stedord","tillægsord","bindeord"],"a":"kendeord","r":"'En' og 'et' er kendeord. De viser, om navneordet er et en-ord eller et et-ord."},
{"l":2590,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Kongen sendte sine tre sønner ud efter en gylden fugl. Den ældste gav op. Den mellemste gav også op. Nu red den yngste af sted.' Hvad sker der efter eventyrets faste mønster?","o":["Den yngste giver også op","Den yngste klarer opgaven","Kongen rider selv af sted","Fuglen flyver hen til kongen"],"a":"Den yngste klarer opgaven","r":"Eventyr bruger tit et fast mønster med tre forsøg. De to første mislykkes, og det tredje lykkes."},
{"l":2611,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et lille rødt dyr med busket hale, der samler nødder. Hvordan staves det?","o":["ejern","ægern","egern","egærn"],"a":"egern","r":"Ordet skrives med g, selvom det lyder som j. Det begynder med e."},
{"l":2630,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Slik, du ikke sluger, og som du kan lave bobler med. Find den rigtige stavemåde.","o":["tyggegumi","tygegummi","tyggegummie","tyggegummi"],"a":"tyggegummi","r":"Ordet består af 'tygge' og 'gummi'. Begge dele har dobbeltkonsonant."},
{"l":2649,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tove fortalte, at hun havde fanget en fisk, der var lige så lang som hendes arm. Næste dag var den lige så lang som bordet. Efter en uge kunne den ikke være i båden.' Hvad er der sket med historien?","o":["Tove overdriver mere og mere","Fisken er vokset i fryseren","Tove har fanget flere fisk","Båden er blevet mindre"],"a":"Tove overdriver mere og mere","r":"Fisken bliver større, hver gang hun fortæller om den. Det er overdrivelse."},
{"l":2668,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Apparatet, der gør dit snavsede tøj rent. Hvordan staves det?","o":["vaskemasjine","vaskemaskine","vasgemaskine","vaske maskine"],"a":"vaskemaskine","r":"Ordet består af 'vaske' og 'maskine'. Det skrives i ét ord."},
{"l":2689,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer efter 'mit': 'Mit ___ tæppe ligger på sengen.'","o":["blødt","blød","bløde","blødest"],"a":"bløde","r":"Efter 'mit' står tillægsordet i bestemt form med -e, ligesom efter 'det': mit bløde tæppe."},
{"l":2710,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Et digt står på korte rækker, som tit ikke går helt ud til kanten. Hvad kaldes sådan en række?","o":["en strofe","et kapitel","et afsnit","en verselinje"],"a":"en verselinje","r":"Et digt består af verselinjer. Flere verselinjer, der hører sammen, kaldes en strofe."},
{"l":2730,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nogle læser for at lære noget, og andre læser for at drømme sig væk. Karl læste mest, når det var svært derhjemme. Så blev bogen et sted, han kunne gå hen.' Hvorfor læste Karl mest, når det var svært?","o":["Fordi han ville glemme for en stund","Fordi han skulle til prøve","Fordi hans lærer forlangte det","Fordi han havde ondt i øjnene"],"a":"Fordi han ville glemme for en stund","r":"Bogen blev et sted, han kunne gå hen. Det betyder, at han kunne slippe væk fra det svære et stykke tid."},
{"l":2749,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord skal have stort forbogstav: 'Mine norske venner bor i bergen og taler norsk.'","o":["norske","bergen","venner","norsk"],"a":"bergen","r":"Bergen er navnet på en by. Tillægsordet 'norske' og sprognavnet 'norsk' skrives med småt."},
{"l":2770,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvorfor lader alle, som om de kan se tøjet i 'Kejserens nye klæder'?","o":["De er bange for væverne","De vil gerne købe tøjet","De vil ikke virke dumme","De har glemt deres briller"],"a":"De vil ikke virke dumme","r":"Væverne har sagt, at dumme mennesker ikke kan se tøjet. Derfor tør ingen sige, at de ikke kan se noget."},
{"l":2791,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig: 'Jeg laver mine ___ efter skole.'","o":["læktier","lektjer","lecktier","lektier"],"a":"lektier","r":"Ordet skrives med e og k, og det slutter på -ier i flertal."},
{"l":2810,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Årets sidste måned. Hvilket ord er stavet rigtigt?","o":["december","desember","decembær","deccember"],"a":"december","r":"Ordet skrives med c, som lyder som s."},
{"l":2830,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad har man gjort, hvis man har 'forhastet' sig?","o":["ventet alt for længe med at svare","handlet for hurtigt uden at tænke","gået roligt hjem fra skolen","brugt alle sine penge i en butik"],"a":"handlet for hurtigt uden at tænke","r":"Den, der forhaster sig, handler uden at tænke sig ordentligt om. Her betyder for-, at det går galt."},
{"l":2853,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord hører ikke til ordfamilien om 'vand'?","o":["vandhane","vandig","vandre","vande"],"a":"vandre","r":"'Vandre' betyder at gå en lang tur og har intet med vand at gøre, selvom det ligner. Man vander med vand, og en vandhane giver vand."},
{"l":2871,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Det kan være svært at ___ en lang tekst på engelsk.'","o":["forstår","forståe","fostå","forstå"],"a":"forstå","r":"Efter 'at' står navnemåden, og den ender her på å uden nutids-r. Husk r'et i 'for-'."},
{"l":2890,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad sker der med vandet i en vandpyt, når det 'fordamper'?","o":["Det bliver til damp og stiger op i luften","Det fryser til is og bliver hårdt","Det bliver blandet med jord og bliver til mudder","Det løber sammen med andet vand i en å"],"a":"Det bliver til damp og stiger op i luften","r":"Når solen varmer vandet, bliver det til damp, som man ikke kan se. Derfor tørrer en vandpyt ud."},
{"l":2907,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvaler ligner fisk, men de er pattedyr. De har lunger og ikke gæller, ligesom mennesker. Ungerne får mælk af deres mor. En hval kan holde vejret længe, men før eller siden må den op til overfladen.' Hvorfor må en hval op til overfladen?","o":["For at finde mælk til sine unger","For at trække vejret med lungerne","For at få luft ned til sine gæller","For at slippe væk fra store fisk"],"a":"For at trække vejret med lungerne","r":"Teksten siger, at hvaler har lunger og kan holde vejret. Man kan derfor slutte, at de skal op efter luft."},
{"l":2927,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kendetegner et 'pattedyr'?","o":["Ungerne klækkes af æg i en rede","Det har fjer og et hårdt næb","Ungerne får mælk af moderen","Det ånder med gæller under vand"],"a":"Ungerne får mælk af moderen","r":"Pattedyr har navn efter patterne, som ungerne dier mælk fra. Både hunde, hvaler og mennesker er pattedyr."},
{"l":2948,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et udråbsord: 'Av, jeg slog mit knæ på bordet!'","o":["slog","knæ","bordet","Av"],"a":"Av","r":"'Av' er et lille udbrud, der viser, at det gør ondt. Sådanne ord kaldes udråbsord."},
{"l":2970,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer efter 'har': 'Vi har ___ en stor kage.'","o":["bagt","bager","bagte","bage"],"a":"bagt","r":"Efter 'har' står den korte tillægsform. 'Bagte' er datid og kan ikke stå efter 'har'."},
{"l":2988,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kom til loppemarked på Birkeskolen på lørdag! 6. klasse sælger legetøj, bøger og hjemmebagte boller. Alle pengene går til klassens tur til Bornholm. Vi åbner klokken 10. Jo mere du køber, jo længere når vi!' Hvad betyder den sidste sætning?","o":["At køberne skal gå langt for at nå loppemarkedet","At jo mere man køber, jo tættere er klassen på turen","At man kan få mere at købe, hvis man kommer tidligt","At jo mere man køber, jo billigere bliver det"],"a":"At jo mere man køber, jo tættere er klassen på turen","r":"'Når længere' skal ikke forstås bogstaveligt. Det betyder, at pengene bringer klassen tættere på turen."},
{"l":3010,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Et digt har ingen rim. Hvordan kan man alligevel se på siden, at det er et digt?","o":["Det har en overskrift øverst på siden","Det er skrevet af en forfatter","Det står i korte linjer og vers","Det fortæller om noget opdigtet"],"a":"Det står i korte linjer og vers","r":"Digte er tit skrevet i verselinjer, der ikke går helt ud til kanten. Overskrift og forfatter har andre tekster også."},
{"l":3025,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er det rigtige? 'Du må gerne ___ blomsterne i vasen.'","o":["sidde","sætter","satte","sætte"],"a":"sætte","r":"Du flytter blomsterne, så ordet er 'sætte'. Efter 'må' står navnemåden."},
{"l":3047,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Mors veninde ___ på et hospital i Odense.'","o":["arbejder","arbejde","abejder","arbejer"],"a":"arbejder","r":"Ordet har r efter det første a, selvom det er svagt i udtalen. D'et før endelsen kan høres, og nutid slutter på -er."},
{"l":3069,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt 'at stige' i datid: 'Alberte ___ på bussen til svømning i går.'","o":["stiger","steg","steget","stige"],"a":"steg","r":"Datid af 'at stige' er 'steg'. 'Steget' er tillægsformen, som bruges efter 'har' eller 'er'."},
{"l":3087,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Karl ville gerne have en hund. Han skrev en liste med alle de ting, han ville gøre: gå tur hver morgen, give mad og børste pels. Listen lagde han på sin fars pude. Nedenunder skrev han: Prøv mig i en måned.' Hvad prøver Karl at gøre?","o":["At huske, hvad han skal lave i næste måned","At give sin far en liste over gode hundenavne","At overbevise sin far om, at han kan klare en hund","At vise sin far, hvordan man børster en pels"],"a":"At overbevise sin far om, at han kan klare en hund","r":"Listen viser, hvor ansvarlig han vil være, og 'Prøv mig' er en opfordring til faren."},
{"l":3107,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Holdet gjorde en stor ___ og vandt kampen.'","o":["fejl","pause","afstand","indsats"],"a":"indsats","r":"En indsats er det arbejde og den energi, man lægger i noget. Holdet gav altså alt, hvad det kunne."},
{"l":3125,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes en person, der har som job at skrive nyheder til en avis?","o":["journalist","forfatter","korrekturlæser","avisbud"],"a":"journalist","r":"En journalist undersøger, hvad der sker, og skriver om det. En forfatter skriver også, men tit bøger og ikke nyheder."},
{"l":3150,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad sker der med Kay i starten af 'Snedronningen'?","o":["Han bliver forvandlet til en svane af en heks","Han får en splint af et troldspejl i øjet","Han bliver taget af røvere på vej hjem","Han falder i søen og fryser til is"],"a":"Han får en splint af et troldspejl i øjet","r":"Splinten fra troldspejlet gør Kay kold og ond. Han får også en splint i hjertet, og derfor ændrer han sig så meget."},
{"l":3168,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg datidsformen, der passer: 'Hele klassen ___ stille og lyttede til historien.'","o":["satte","sat","sad","sidde"],"a":"sad","r":"Eleverne var i ro på deres pladser, så det er datid af 'sidde'."},
{"l":3190,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find det spørgende stedord: 'Hvem har taget den sidste bolle?'","o":["taget","sidste","bolle","Hvem"],"a":"Hvem","r":"'Hvem' bruges til at spørge efter en person. Derfor er det et spørgende stedord."},
{"l":3208,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Eleverne i 5.C på Engskolen har i et halvt år samlet affald på stranden hver måned. I alt har de samlet 212 kilo. Nu har de lavet en udstilling af plasten på biblioteket. – Vi vil have folk til at tænke, før de smider noget, siger Ibrahim fra klassen.' Hvorfor har klassen lavet udstillingen?","o":["For at få folk til ikke at smide affald","For at tjene penge til en klassetur","For at få biblioteket til at bruge mindre plast","For at få folk til at samle affald med dem"],"a":"For at få folk til ikke at smide affald","r":"Ibrahim siger selv, hvad målet er: Folk skal tænke sig om, før de smider noget."},
{"l":3226,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I en mose er der næsten ingen ilt i vandet, og vandet er surt. Derfor rådner ting meget langsomt. Det er grunden til, at arkæologer har fundet tøj og træting fra oldtiden i danske moser. På en mark ville de samme ting være forsvundet for længst.' Hvorfor bliver gamle ting bedre bevaret i en mose end på en mark?","o":["Fordi der er mere ilt i vandet i mosen","Fordi ting rådner langsommere i mosen","Fordi arkæologer helst leder i moser","Fordi det sure vand vasker tingene rene"],"a":"Fordi ting rådner langsommere i mosen","r":"Teksten forklarer, at surt vand med lidt ilt gør, at tingene ikke rådner så hurtigt."},
{"l":3245,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: '»Kom så!« Råbte træneren til Ella.'?","o":["Kom","træneren","Råbte","Ella"],"a":"Råbte","r":"Sætningen er ikke slut efter den direkte tale. 'råbte træneren' fortsætter den, så udsagnsordet skal have lille bogstav."},
{"l":3267,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om Freja og klaveret står i førnutid?","o":["Freja spillede klaver.","Freja spiller klaver.","Freja havde spillet klaver.","Freja har spillet klaver."],"a":"Freja har spillet klaver.","r":"Førnutid dannes med 'har' og tillægsform. Med 'havde' i stedet bliver det førdatid."},
{"l":3289,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Min onkel er ___ og står op klokken fire hver morgen.'","o":["bager","bagere","bagerer","bagger"],"a":"bager","r":"Der er kun én onkel, så navneordet står i ental og ender på -er. Flertal ville ende på -ere."},
{"l":3302,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren siger: 'Jeg taler for døve øren.' Hvad mener hun?","o":["Hun hvisker, fordi eleverne læser","Der er ingen, der vil lytte til hende","Klassen skal lære tegnsprog i dag","Hun har ondt i ørerne af larmen"],"a":"Der er ingen, der vil lytte til hende","r":"At tale for døve øren er at sige noget, som andre ikke tager sig af. Vendingen handler ikke om rigtig hørelse."},
{"l":3325,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken forstavelse gør 'tilfreds' til sit modsatte?","o":["mis-","van-","u-","be-"],"a":"u-","r":"Utilfreds er det modsatte af tilfreds. Forstavelsen u- bruges til at vende mange tillægsord om, som i ulykkelig og usikker."}
